// SiteFacts gathers the targeted Catalyst Center's site hierarchy.
//
// It emits site_name_hierarchy for each site rather than the bare name,
// because the bare name is only the last path component: two buildings in
// different regions can share one, so anything grouping by site has to use
// the full path or it will merge sites that are not the same place.
func SiteFacts(ctx context.Context, rc sdk.RunbookContext, device inventory.InventoryItem, params map[string]any) (collection.Result, error) {
	client, err := clientForDevice(rc, device, params)
	if err != nil {
		return collection.Result{}, err
	}
	defer func() { _ = client.Close() }()

	sites, err := client.ListSites(ctx)
	if err != nil {
		return collection.Result{}, fmt.Errorf("net.catalyst.site_facts: %w", err)
	}

	facts := make([]map[string]any, 0, len(sites))
	for _, s := range sites {
		facts = append(facts, map[string]any{
			"id":                  s.ID,
			"name":                s.Name,
			"site_name_hierarchy": s.NameHierarchy,
		})
	}

	if err := rc.EmitFact("sites", facts); err != nil {
		return collection.Result{}, err
	}
	if err := rc.EmitFact("site_count", len(facts)); err != nil {
		return collection.Result{}, err
	}
	return collection.Result{Changed: false}, nil
}
